import {AudioCache} from '../../listen-upstream/realtime/cache'
import {validateScene,type Scene} from './contract'
import {SceneGraph,type PCM} from './graph'
import {prepareScene} from './prepare'
type Entry={id:string;sha256:string;url:string;title:string;fromTitle:string;toTitle:string;duration:number}
type Dependencies={read?:(path:string,signal:AbortSignal)=>Promise<any>;bytes?:(path:string,signal:AbortSignal)=>Promise<ArrayBuffer>;create?:()=>AudioContext}
const hex=/^[a-f0-9]{64}$/
export function validateSceneIndex(v:any):Entry[]{if(v?.schema!=='harbeat.longmix-index.v1'||!Array.isArray(v.scenes)||v.scenes.length>8)throw Error('长混试验目录无效');const seen=new Set();for(const e of v.scenes){if(!e||!hex.test(e.id)||!hex.test(e.sha256)||e.url!=='/listen/longmix-lab/v1/'+e.sha256+'.json'||seen.has(e.id)||!['title','fromTitle','toTitle'].every(k=>typeof e[k]==='string'&&e[k].length>0&&e[k].length<=300)||!Number.isFinite(e.duration)||e.duration<=32||e.duration>64)throw Error('长混试验目录无效');seen.add(e.id)}return v.scenes}
export class LongmixRun{
 private rows:Entry[]=[];private ctx:AudioContext|null=null;private audioInit:Promise<void>|null=null;private cache:AudioCache|null=null;private monitor:AudioWorkletNode|null=null;private graph:SceneGraph|null=null;private scene:Scene|null=null;private pcm:PCM|null=null;private revision=0;private starting=false;private controller:AbortController|null=null;private variant:'long'|'reference'='long';private phase='idle';private busy=false;private error='';private status='普通混音仍可从返回入口使用';private logs:Record<string,unknown>[]=[];private timer:ReturnType<typeof setInterval>|null=null;private requestId='';private dead=false
 constructor(private base:URL,private changed:()=>void,private host?:{requestFocus:()=>boolean;exportLog?:(text:string,format:string)=>void},private deps:Dependencies={}){}
 private log=(kind:string,data:Record<string,unknown>={})=>{this.logs.push({kind,wallTime:new Date().toISOString(),contextSec:this.ctx?.currentTime??0,...data});if(this.logs.length>2000)this.logs.shift()}
 private async bytes(path:string,signal:AbortSignal){if(this.deps.bytes)return this.deps.bytes(path,signal);const r=await fetch(new URL(path,this.base),{cache:'no-store',redirect:'error',signal:AbortSignal.any([signal,AbortSignal.timeout(20000)])});if(!r.ok)throw Error('长混试验资料未就绪 '+r.status);const reader=r.body?.getReader();if(!reader)throw Error('长混试验资料为空');const chunks:Uint8Array[]=[];let n=0;try{for(;;){const x=await reader.read();if(x.done)break;n+=x.value.byteLength;if(n>2*1024*1024)throw Error('长混试验资料超过预算');chunks.push(x.value)}}finally{await reader.cancel().catch(()=>{});reader.releaseLock()}const out=new Uint8Array(n);let i=0;for(const c of chunks){out.set(c,i);i+=c.length}return out.buffer}
 private read(path:string,signal:AbortSignal){return this.deps.read?this.deps.read(path,signal):this.bytes(path,signal).then(b=>JSON.parse(new TextDecoder().decode(b)))}
 async prepare(){const c=new AbortController();this.controller?.abort();this.controller=c;try{this.rows=validateSceneIndex(await this.read('/listen/longmix-lab/v1/index.json',c.signal));this.status=this.rows.length?'选择同一曲对的普通交接或鼓循环长混试听':'暂时没有通过检查的长混素材';return this.rows}catch(e){this.error=(e as Error).message;throw e}}
 private async audio():Promise<void>{
  if(this.dead)throw new DOMException('已关闭','AbortError');if(this.ctx&&this.monitor&&this.cache)return
  if(this.audioInit){await this.audioInit.catch(()=>{});return this.audio()}
  const revision=this.revision,ctx=(this.deps.create??(()=>new AudioContext({sampleRate:44100,latencyHint:'interactive'})))();let monitor:AudioWorkletNode|null=null,cache:AudioCache|null=null
  const alive=()=>{if(this.dead||revision!==this.revision)throw new DOMException('已取消','AbortError')}
  const task=(async()=>{try{await ctx.audioWorklet.addModule(new URL('v3-device-clock.js',location.href));alive();monitor=new AudioWorkletNode(ctx,'v3-clock',{outputChannelCount:[2]});monitor.connect(ctx.destination);monitor.port.onmessage=({data})=>{this.log(data.kind==='audio_health'?'audio_health':'audio_observation',data);this.changed()};cache=new AudioCache(ctx,this.base,s=>{this.status=s;this.changed()});await ctx.suspend();alive();this.ctx=ctx;this.monitor=monitor;this.cache=cache;this.timer=setInterval(()=>this.tick(),100)}catch(error){cache?.dispose();monitor?.disconnect();await ctx.close().catch(()=>{});throw error}})()
  this.audioInit=task;try{await task}finally{if(this.audioInit===task)this.audioInit=null}
 }
 async loadScene(id:string,variant:'long'|'reference'){
  const row=this.rows.find(e=>e.id===id);if(!row||!['long','reference'].includes(variant))throw Error('请选择已发布的两来源场景')
  this.stop();const revision=++this.revision,c=this.controller=new AbortController();this.busy=true;this.error='';this.phase='preparing';this.status='正在核对来源并准备本机声部';this.changed()
  try{const bytes=await this.bytes(row.url,c.signal),digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(v=>v.toString(16).padStart(2,'0')).join('');if(digest!==row.sha256)throw Error('长混方案内容指纹不一致');const scene=validateScene(JSON.parse(new TextDecoder().decode(bytes)));if(scene.id!==row.id)throw Error('长混场景身份不一致');c.signal.throwIfAborted();await this.audio();c.signal.throwIfAborted();const pcm=await prepareScene(scene,this.ctx!,this.cache!,this.base,variant,c.signal);if(this.dead||revision!==this.revision)throw new DOMException('已取消','AbortError');this.scene=scene;this.pcm=pcm;this.variant=variant;this.phase='ready';this.status='素材已校验，可开始试听';this.log('scene_prepared',{sceneId:id,variant,approvalProducer:scene.producer,implementationSha256:scene.implementationSha256,sourceProof:scene.sources,evidence:scene.evidence})}
  catch(e){if(revision===this.revision){this.phase='failed';this.error=(e as Error).message;this.status='本次长混未启用，可返回普通混音';this.log('scene_prepare_failed',{reason:this.error})}throw e}
  finally{if(revision===this.revision)this.busy=false;this.changed()}
 }
 async start(){if(!this.pcm||!this.scene||!this.ctx||!this.monitor||this.busy||this.starting||this.phase!=='ready')throw Error('长混素材尚未就绪，请先准备');if(this.host&&!this.host.requestFocus())throw Error('请回到前台后播放');const revision=this.revision,ctx=this.ctx,scene=this.scene,pcm=this.pcm,monitor=this.monitor;this.starting=true
  try{await ctx.resume();if(this.dead||revision!==this.revision||this.phase!=='ready')throw new DOMException('启动已取消','AbortError');this.requestId=scene.id+':'+this.logs.length;this.graph=new SceneGraph(ctx,monitor,scene,pcm,this.variant,ctx.currentTime+.15,this.log);this.phase='playing';this.status='原曲引入后按 Jetson 声部编排执行';this.arm();this.changed()}
  catch(e){if(revision===this.revision){this.graph?.stop();this.graph=null;await ctx.suspend();this.phase='failed';this.error=(e as Error).message}throw e}finally{this.starting=false}}
 private arm(exitOnly=false){if(!this.graph||!this.ctx||!this.monitor)return;this.monitor.port.postMessage({kind:'cancel',planId:this.requestId});const events=[{name:'B 原曲接管',frame:Math.round((this.graph.sceneAt+this.graph.exit.at)*this.ctx.sampleRate)}];if(!exitOnly)events.unshift({name:'长混声部开始',frame:Math.round(this.graph.sceneAt*this.ctx.sampleRate)});this.monitor.port.postMessage({kind:'arm',events:events.map(e=>({...e,planId:this.requestId,requestId:this.requestId}))})}
 requestExit(){if(!this.graph||!this.ctx||this.ctx.state!=='running')throw Error('请先播放再选择退出点');const e=this.graph.requestExit();if(!e)throw Error('附近没有尚可安排的退出点，将按原计划接管');this.arm(true);this.status='将在已批准的第 '+Math.round(e.at*this.scene!.bpm/240)+' 小节退出';this.changed();return e}
 async pause(reason='user'){if(this.ctx){await this.ctx.suspend();this.log('scene_pause',{reason,position:this.graph?.position??0});this.changed()}}
 async resume(){if(!this.graph||!this.ctx||this.phase==='finished')throw Error('请重新准备试听');if(this.host&&!this.host.requestFocus())throw Error('请回到前台后继续');await this.ctx.resume();this.log('scene_resume',{position:this.graph.position});this.changed()}
 private tick(){if(!this.graph||!this.ctx||this.ctx.state!=='running')return;if(this.graph.finished){this.log('scene_completed',{sceneId:this.scene?.id,variant:this.variant,exit:this.graph.exit});this.graph.stop();this.graph=null;this.phase='finished';this.status='试听完成，可返回普通混音或重新准备对照';void this.ctx.suspend()}else if(this.graph.position>=this.graph.exit.at&&this.phase!=='tail'){this.phase='tail';this.status='B 原曲已接管，继续原速播放';this.log('scene_native_takeover',{position:this.graph.position,exit:this.graph.exit})}this.changed()}
 stop(){this.revision++;this.controller?.abort();this.controller=null;this.graph?.stop();this.graph=null;this.monitor?.port.postMessage({kind:'clear'});this.pcm=null;this.scene=null;this.busy=false;this.phase='idle';this.error='';if(this.ctx)void this.ctx.suspend();this.log('scene_stopped');this.changed()}
 snapshot(){const graph=this.graph,playing=!!graph&&this.ctx?.state==='running',paused=!!graph&&this.ctx?.state==='suspended';return{mode:'longmix',ready:true,playing,paused,busy:this.busy,position:graph?.position??0,duration:this.scene?.duration??0,status:this.status,error:this.error,scene:this.scene?{id:this.scene.id,title:this.scene.title,variant:this.variant,phase:paused?'paused':this.phase,exits:this.scene.exits.map(e=>e.at),selectedExit:graph?.exit.at??null}:null,logCount:this.logs.length}}
 export(){return{schema:'harbeat.longmix-lab-session.v1',mode:'longmix',foregroundOnly:true,sourceExecution:'Jetson-approved two-source scene; device mixed stems',scene:this.scene,variant:this.variant,state:this.snapshot(),logs:this.logs,limitations:['执行时钟观察不代表扬声器或蓝牙延迟','人工听感尚需试听']}}
 dispose(){this.dead=true;this.stop();if(this.timer)clearInterval(this.timer);this.cache?.dispose();this.monitor?.disconnect();void this.ctx?.close();this.ctx=null}
}
